class Solution {
    private int reverse(int value){
        int result=0;
        while(value>0){
            result=result*10+value%10;
            value/=10;
        }
        return result;
    }
    public int countNicePairs(int[] nums){
        Map<Integer,Integer> frequency=new HashMap<>();
        long answer=0;
        for(int value:nums){
            int key=value-reverse(value);
            answer+=frequency.getOrDefault(key,0);
            frequency.put(key,frequency.getOrDefault(key,0)+1);
        }
        return (int)(answer%1_000_000_007);
    }
}

code.kotlin:
class Solution {
    private fun reverse(valueInput:Int):Int{
        var value=valueInput;
        var result=0;
        while(value>0){
            result=result*10+value%10;
            value/=10
        };
        return result
    };
    fun countNicePairs(nums:IntArray):Int{
        val frequency=mutableMapOf<Int,Int>();
        var answer=0L;
        for(value in nums){
            val key=value-reverse(value);
            answer+=frequency[key]?:0;
            frequency[key]=(frequency[key]?:0)+1
        };
        return (answer%1_000_000_007).toInt()
    }
}

